// Adversarial review of src/math (M1a) against an independent oracle.
// Ground truth is generated by gen_fixtures.py (Python fractions + decimal;
// sympy is not installed) into the *.json files next to this file.
// Regenerate with: python3 test/adversarial/math-oracle/gen_fixtures.py
//
// Rule enforced throughout: a definite answer (true / false) must be right.
// undefined ("cannot verify") is tolerated but counted and printed.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import * as R from '../../../src/math/rational.js';
import * as S from '../../../src/math/surd.js';
import { toPoly, degree } from '../../../src/math/poly.js';
import { equivExpr, sameSides, isMultiple, sameSolutions, WHERE_DEFINED } from '../../../src/math/equiv.js';
import { solve } from '../../../src/math/solve.js';
import { print } from '../../../src/math/print.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const load = (f) => JSON.parse(readFileSync(join(HERE, f), 'utf8'));

const Q = ([n, d]) => ({ n: BigInt(n), d: BigInt(d) });
const qs = (x) => `${x.n}/${x.d}`;
const surd = (terms) => ({ terms: terms.map(([n, d, r]) => ({ coef: Q([n, d]), rad: BigInt(r) })) });
const surdStr = (s) => s.terms.map((t) => `${qs(t.coef)}*sqrt(${t.rad})`).join(' + ') || '0';

/** Convert fixture trees (q as [n, d] strings) to section 11 Nodes. */
function node(t) {
  switch (t.t) {
    case 'num': return { t: 'num', q: Q(t.q) };
    case 'var': return t;
    case 'add': case 'mul': return { t: t.t, args: t.args.map(node) };
    case 'neg': case 'group': return { t: t.t, arg: node(t.arg) };
    case 'frac': return { t: 'frac', num: node(t.num), den: node(t.den) };
    case 'pow': return { t: 'pow', base: node(t.base), exp: node(t.exp) };
    case 'root': return { t: 'root', index: t.index, radicand: node(t.radicand) };
    default: throw new Error(`bad tree ${t.t}`);
  }
}
const eqn = (e) => ({ t: 'eq', lhs: node(e.lhs), rhs: node(e.rhs) });

// ------------------------------------------------------------------ rationals

test('rational arithmetic matches Python Fraction (12000 cases, huge/negative/zero)', () => {
  const rows = load('rational.json');
  let bad = [];
  for (const r of rows) {
    const a = R.q(BigInt(r.a_raw[0]), BigInt(r.a_raw[1]));
    const b = R.q(BigInt(r.b_raw[0]), BigInt(r.b_raw[1]));
    const chk = (name, got, want) => { if (qs(got) !== `${want[0]}/${want[1]}`) bad.push(`${name}(${qs(a)}, ${qs(b)}) = ${qs(got)}, want ${want.join('/')}`); };
    chk('q', a, r.a); chk('q', b, r.b);
    chk('add', R.add(a, b), r.add); chk('sub', R.sub(a, b), r.sub); chk('mul', R.mul(a, b), r.mul);
    chk('neg', R.neg(a), r.neg);
    if (r.div) chk('div', R.div(a, b), r.div); else assert.throws(() => R.div(a, b));
    if (R.cmp(a, b) !== r.cmp) bad.push(`cmp(${qs(a)}, ${qs(b)}) = ${R.cmp(a, b)}, want ${r.cmp}`);
    if (R.qeq(a, b) !== (r.cmp === 0)) bad.push(`qeq(${qs(a)}, ${qs(b)})`);
  }
  assert.deepEqual(bad.slice(0, 10), []);
});

// ------------------------------------------------------------------ surds

test('surd add / mul / seq / sign match the Python oracle (10000 pairs)', () => {
  const { pairs } = load('surd.json');
  const bad = [];
  for (const r of pairs) {
    const a = surd(r.a);
    const b = surd(r.b);
    const sum = S.sadd(a, b);
    const prod = S.smul(a, b);
    if (!S.seq(sum, surd(r.add))) bad.push(`sadd: ${surdStr(a)} + ${surdStr(b)} = ${surdStr(sum)}`);
    if (!S.seq(prod, surd(r.mul))) bad.push(`smul: ${surdStr(a)} * ${surdStr(b)} = ${surdStr(prod)}`);
    if (S.seq(a, b) !== r.eq) bad.push(`seq ${surdStr(a)} vs ${surdStr(b)}`);
    if (S.scmp(a, b) !== r.cmp) bad.push(`scmp ${surdStr(a)} vs ${surdStr(b)}: ${S.scmp(a, b)} want ${r.cmp}`);
    if (S.ssign(a) !== r.signA) bad.push(`ssign ${surdStr(a)}`);
    if (a.terms.length > 0) {
      const inv = S.sinv(a);
      if (!inv || !S.seq(S.smul(a, inv), S.SONE)) bad.push(`sinv ${surdStr(a)}`);
      else if (S.ssign(inv) !== r.signA) bad.push(`sign of sinv ${surdStr(a)}`);
    } else if (S.sinv(a) !== undefined) bad.push('sinv(0) defined');
    // canonical form: rads ascending, squarefree, no zero coefficients
    for (const s of [sum, prod]) {
      for (let i = 0; i < s.terms.length; i++) {
        if (s.terms[i].coef.n === 0n) bad.push('zero coefficient kept');
        if (i && s.terms[i - 1].rad >= s.terms[i].rad) bad.push('rads not ascending');
      }
    }
  }
  assert.deepEqual(bad.slice(0, 10), []);
});

test('sqrtQ matches trial-division square part (3000 rationals incl. negatives)', () => {
  const { sqrtQ: rows } = load('surd.json');
  const bad = [];
  for (const r of rows) {
    const got = S.sqrtQ(Q(r.x));
    if (r.sqrt === null) { if (got !== undefined) bad.push(`sqrtQ(${r.x.join('/')}) defined`); continue; }
    if (!got || !S.seq(got, surd(r.sqrt))) bad.push(`sqrtQ(${r.x.join('/')}) = ${got && surdStr(got)}`);
  }
  assert.deepEqual(bad.slice(0, 10), []);
});

// ------------------------------------------------------------------ polynomials

test('toPoly expansion matches the Python multivariate oracle (4000 trees, x / x,y / x,y,z)', () => {
  const rows = load('poly.json');
  const bad = [];
  let undef = 0;
  for (const r of rows) {
    const n = node(r.tree);
    const p = toPoly(n);
    if (!p) { undef++; continue; }
    const got = {};
    for (const [k, c] of p.terms) got[k] = [String(c.n), String(c.d)];
    const want = r.poly;
    const ks = new Set([...Object.keys(got), ...Object.keys(want)]);
    for (const k of ks) {
      if (!got[k] || !want[k] || got[k].join('/') !== want[k].join('/')) { bad.push(`${print(n)}: term ${k} got ${got[k]} want ${want[k]}`); break; }
    }
    if (degree(p) !== r.degree) bad.push(`degree ${print(n)} = ${degree(p)} want ${r.degree}`);
  }
  console.log(`# toPoly: ${rows.length} trees, undefined on ${undef}`);
  assert.deepEqual(bad.slice(0, 10), []);
});

// ------------------------------------------------------------------ equivExpr

/** Independent float check that a witness separates the two sides (JS source from the generator). */
function floatAt(js, env) {
  const names = Object.keys(env);
  const vals = names.map((k) => Number(env[k].n) / Number(env[k].d));
  // eslint-disable-next-line no-new-func
  return Function(...names, `return ${js};`)(...vals);
}

test('equivExpr: generated TRUE / FALSE pairs never get a wrong definite verdict', () => {
  const { rows } = load('equiv.json');
  const stats = {};
  const bad = [];
  for (const r of rows) {
    const a = node(r.a);
    const b = node(r.b);
    const st = (stats[`${r.label ? 'T' : 'F'} ${r.family}`] ??= { n: 0, true: 0, false: 0, undef: 0, noWitness: 0, missingNote: 0 });
    for (const [x, y, xjs, yjs] of [[a, b, r.ajs, r.bjs], [b, a, r.bjs, r.ajs]]) {
      st.n++;
      const res = equivExpr(x, y, r.as);
      const tag = `${print(x)}  vs  ${print(y)}  as=${JSON.stringify(r.as)}`;
      if (res.equal === undefined) { st.undef++; continue; }
      st[String(res.equal)]++;
      if (res.equal !== r.label) { bad.push(`[${r.family}] WRONG ${res.equal}: ${tag} note=${res.note}`); continue; }
      if (res.equal === true && r.note && !(res.note ?? '').startsWith(WHERE_DEFINED)) {
        st.missingNote++;
        bad.push(`[${r.family}] true but no where-defined note: ${tag}`);
      }
      if (res.equal === false) {
        if (!res.witness) { st.noWitness++; continue; }
        const fx = floatAt(xjs, res.witness);
        const fy = floatAt(yjs, res.witness);
        const sep = Number.isFinite(fx) && Number.isFinite(fy) && Math.abs(fx - fy) > 1e-9 * (1 + Math.abs(fx) + Math.abs(fy));
        const tooBig = !Number.isFinite(fx) || !Number.isFinite(fy) ? false : Math.abs(fx) > 1e15 || Math.abs(fy) > 1e15;
        if (!sep && !tooBig) bad.push(`[${r.family}] witness ${JSON.stringify(Object.fromEntries(Object.entries(res.witness).map(([k, v]) => [k, qs(v)])))} does not separate ${tag}: ${fx} vs ${fy}`);
        for (const asm of r.as) {
          const w = res.witness[asm.name];
          if (!w) continue;
          if ((asm.rel === 'nonneg' && w.n < 0n) || (asm.rel === 'pos' && w.n <= 0n) || (asm.rel === 'nonzero' && w.n === 0n)) bad.push(`[${r.family}] witness violates ${asm.name} ${asm.rel}: ${tag}`);
        }
      }
    }
  }
  const lines = Object.entries(stats).sort().map(([k, v]) => `# ${k.padEnd(30)} n=${v.n} true=${v.true} false=${v.false} undef=${v.undef} noWitness=${v.noWitness}`);
  console.log(lines.join('\n'));
  assert.deepEqual(bad.slice(0, 15), []);
});

// ------------------------------------------------------------------ solve

test('solve matches the exact oracle on 6000 random linear / quadratic equations', () => {
  const rows = load('solve.json');
  const bad = [];
  let undef = 0;
  let big = 0;
  for (const r of rows) {
    const e = { t: 'eq', lhs: node(r.lhs), rhs: node(r.rhs) };
    const got = solve(e, 'x');
    const tag = `${print(e)}`;
    if (got === undefined) { undef++; continue; }
    if (r.sol.kind === 'big') {
      big++;
      // (2a r + b)^2 = D for each root
      const a = S.fromQ(Q(r.a)); const b = S.fromQ(Q(r.b)); const D = S.fromQ(Q(r.sol.D));
      if (got.kind !== 'finite' || got.roots.length !== 2) { bad.push(`big-D ${tag}: ${got.kind}`); continue; }
      for (const x of got.roots) {
        const t = S.sadd(S.smul(S.sscale(a, R.q(2)), x), b);
        if (!S.seq(S.smul(t, t), D)) bad.push(`big-D root wrong ${tag}`);
      }
      continue;
    }
    if (got.kind !== r.sol.kind) { bad.push(`${tag}: kind ${got.kind} want ${r.sol.kind}`); continue; }
    if (got.kind !== 'finite') continue;
    const want = r.sol.roots.map(surd);
    if (got.roots.length !== want.length || !got.roots.every((x, i) => S.seq(x, want[i]))) {
      bad.push(`${tag}: roots ${got.roots.map(surdStr)} want ${want.map(surdStr)}`);
    }
  }
  console.log(`# solve: ${rows.length} equations, undefined on ${undef}, big-discriminant checked ${big}`);
  assert.deepEqual(bad.slice(0, 10), []);
});

// ------------------------------------------------------------------ equations

test('sameSides / isMultiple / sameSolutions on generated equations', () => {
  const rows = load('equations.json');
  const bad = [];
  const st = {};
  for (const r of rows) {
    const s = (st[`${r.kind} expect=${r.expect}`] ??= { n: 0, ok: 0, undef: 0 });
    s.n++;
    let got;
    let tag;
    if (r.kind === 'sameSides') { const g = eqn(r.got); const w = eqn(r.want); got = sameSides(g, w); tag = `${print(g)} || ${print(w)}`; }
    else if (r.kind === 'isMultiple') { const g = eqn(r.got); const o = eqn(r.orig); got = isMultiple(g, o); tag = `${print(g)} || ${print(o)}`; }
    else {
      const a = eqn(r.a); const b = eqn(r.b);
      const res = sameSolutions(a, b, 'x');
      got = res.equal;
      tag = `${print(a)} || ${print(b)}`;
      if (got === false) {
        // witness must solve exactly one of the two (oracle root lists)
        const w = res.witness;
        const inA = r.rootsA.some((x) => S.seq(S.fromQ(Q(x)), w));
        const inB = r.rootsB.some((x) => S.seq(S.fromQ(Q(x)), w));
        if (inA === inB) bad.push(`sameSolutions witness ${surdStr(w)} does not separate ${tag}`);
      }
    }
    if (got === undefined) { s.undef++; continue; }
    if (got !== r.expect) bad.push(`${r.kind} WRONG ${got}: ${tag}`); else s.ok++;
  }
  console.log(Object.entries(st).map(([k, v]) => `# ${k.padEnd(28)} n=${v.n} ok=${v.ok} undef=${v.undef}`).join('\n'));
  assert.deepEqual(bad.slice(0, 10), []);
});

// ------------------------------------------------------------------ random-tree fuzz

test('equivExpr soundness on 14500 random tree pairs labelled by a Decimal oracle', () => {
  const rows = load('fuzz.json');
  const bad = [];
  const st = { T: { true: 0, false: 0, undef: 0 }, F: { true: 0, false: 0, undef: 0 } };
  for (const r of rows) {
    const a = node(r.a);
    const b = node(r.b);
    for (const [x, y] of [[a, b], [b, a]]) {
      const res = equivExpr(x, y, r.as);
      st[r.label ? 'T' : 'F'][res.equal === undefined ? 'undef' : String(res.equal)]++;
      if (res.equal !== undefined && res.equal !== r.label) {
        bad.push(`WRONG ${res.equal} (oracle ${r.label}): ${print(x)}  vs  ${print(y)}  as=${JSON.stringify(r.as)} note=${res.note} w=${res.witness && JSON.stringify(Object.fromEntries(Object.entries(res.witness).map(([k, v]) => [k, qs(v)])))}`);
      }
    }
  }
  console.log(`# fuzz oracle-true : ${JSON.stringify(st.T)}\n# fuzz oracle-false: ${JSON.stringify(st.F)}`);
  assert.deepEqual(bad.slice(0, 15), []);
});
